import{_ as s,l,o as e,c as d,v as o,p as i,x as t,d as n,i as E,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"load / store 队列与内存消歧","description":"","frontmatter":{"title":"load / store 队列与内存消歧","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lsq-disambiguation.md","filePath":"cs/lsq-disambiguation.md","lastUpdated":1789023840000}'),A={name:"cs/lsq-disambiguation.md"};function p(h,a,C,u,B,_){const r=l("Mermaid");return e(),d("div",null,[a[1]||(a[1]=o('<h1 id="load-store-队列与内存消歧" tabindex="-1">load / store 队列与内存消歧 <a class="header-anchor" href="#load-store-队列与内存消歧" aria-label="Permalink to &quot;load / store 队列与内存消歧&quot;">​</a></h1><div class="epigraph"><p>寄存器重命名消掉假相关；两条访存是否撞同一地址，要等有效地址算完才知道。队列把未提交的 store 托住，load 在里面搜转发。</p><footer>—— 据 Chao, Breach, and Shen；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/issue-queue-wakeup">上一课</a>让 ALU 按物理寄存器就绪发射。load/store 的操作数可以齐了，<strong>地址还没算</strong>；即使算了，年轻 load 与年长 store 是否别名也未知。本课不重讲 IQ 选择。缺口是<strong>内存消歧</strong>：在不知道地址时如何（或不如何）让 load 提前，以及 store 如何在提交前对 cache 不可见。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>store x1, 0(x2)</code> 后面的 <code>load x3, 0(x4)</code>：若 <code>x2==x4</code>，load 必须拿到 store 的数据（或等它提交后从 cache 读）；若地址不同，load 可以去 cache。地址在 AGU 之后才有，比寄存器 RAW 晚一截。缺口不是再加物理寄存器，而是<strong>按程序序排好的 load 队列与 store 队列，用地址比较做转发或让路</strong>。</p><p><span class="marginnote">store 在 ROB 提交前只存在于 store queue；提交才写 cache，才能被 <a href="/cs/mesi-protocol">MESI</a> 看见。这与推测恢复一致。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>译码时 load/store 按序进入 LQ/SQ。AGU 写回有效地址后：</p><ul><li>load 在 SQ 里搜年长、地址重叠的 store：命中则转发数据（可能只要部分字节）；若年长 store 地址未就绪，则要么等，要么推测「不冲突」并发出 cache 请求。</li><li>若后来发现冲突，replay load 并冲刷依赖（或只重执行该 load）。</li></ul>',9)),(e(),i(c,null,{default:t(()=>[E(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20AGU%5B%22AGU%20%E5%86%99%E6%9C%89%E6%95%88%E5%9C%B0%E5%9D%80%22%5D%20--%3E%20CAM%5B%22SQ%20%E6%8C%89%E5%9C%B0%E5%9D%80%20CAM%22%5D%0A%20%20CAM%20--%3E%7C%22%E9%87%8D%E5%8F%A0%E4%B8%94%E6%95%B0%E6%8D%AE%E9%BD%90%22%7C%20FWD%5B%22store-to-load%20%E8%BD%AC%E5%8F%91%22%5D%0A%20%20CAM%20--%3E%7C%22%E4%B8%8D%E9%87%8D%E5%8F%A0%22%7C%20CACHE%5B%22%E5%8F%91%E5%BE%80%20cache%22%5D%0A%20%20CAM%20--%3E%7C%22%E5%B9%B4%E9%95%BF%E5%9C%B0%E5%9D%80%E6%9C%AA%E7%9F%A5%22%7C%20SPEC%5B%22%E6%8E%A8%E6%B5%8B%E5%8F%91%E5%87%BA%E6%88%96%E7%AD%89%E5%BE%85%22%5D%0A%20%20SPEC%20--%3E%7C%22%E4%BA%8B%E5%90%8E%E5%86%B2%E7%AA%81%22%7C%20REPLAY%5B%22%E9%87%8D%E6%89%A7%E8%A1%8C%20%2F%20%E5%86%B2%E5%88%B7%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>消歧失败有两类代价：等（损失 ILP）和猜错（replay，类似误预测但通常更局部）。多核下，转发只看见本核 SQ；他核的 store 靠一致性事务，不在 SQ 里。字节重叠、非对齐、向量宽 load 让 CAM 匹配变成区间重叠，而不是 64 位相等。</p><p>与 <a href="/cs/ooo-rob">ROB</a>：LQ/SQ 项数是窗口的第四个上限，常比 PRF 先满。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入存储集：那是用 PC 预测「会不会撞」，把「等未知地址」变成可学习的事，下一课。也不把 x86 的 store forwarding 对齐限制写成通用 ISA。原子 RMW 的队列行为是一致性进阶课。</p><p>后课默认：load 可以在年长 store 地址未知时推测发出；冲突则 replay。用历史预测依赖，是下一课存储集。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LQ/SQ 按程序序托住访存；地址 CAM 做转发或放行。</li><li>地址未知时只能等或推测；猜错要 replay。</li><li>用 PC 预测依赖对是下一课存储集。</li><li>出处：Hennessy and Patterson, <em>CA:AQA</em>；乱序访存队列的经典实现传统。</li></ul>',8))])}const D=s(A,[["render",p]]);export{f as __pageData,D as default};
